package com.example.smartpantrymanager.data; import android.content.*;import android.database.sqlite.*;import android.database.*;import com.example.smartpantrymanager.model.*;import java.util.*; public class DatabaseHelper extends SQLiteOpenHelper { public DatabaseHelper(Context c){super(c,"smart_pantry.db",null,1);} public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE pantry_item(id INTEGER PRIMARY KEY AUTOINCREMENT,ingredient_name TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,expiry_date TEXT,category TEXT)");d.execSQL("CREATE TABLE recipe(id INTEGER PRIMARY KEY AUTOINCREMENT,recipe_name TEXT NOT NULL,instructions TEXT NOT NULL)");d.execSQL("CREATE TABLE recipe_ingredient(id INTEGER PRIMARY KEY AUTOINCREMENT,recipe_id INTEGER NOT NULL,ingredient_name TEXT NOT NULL,required_quantity REAL DEFAULT 1,unit TEXT,FOREIGN KEY(recipe_id) REFERENCES recipe(id) ON DELETE CASCADE)");seed(d);} void seed(SQLiteDatabase d){add(d,"Egg Sandwich","Toast bread, cook the egg, add tomato and assemble.",new String[]{"bread","egg","tomato"});add(d,"Tomato Pasta","Cook pasta, sauté onion and tomato, then combine.",new String[]{"pasta","tomato","onion"});add(d,"Rice and Beans","Cook rice and combine with beans and onion.",new String[]{"rice","beans","onion"});add(d,"Chicken Rice","Cook chicken and rice, then combine with onion.",new String[]{"chicken","rice","onion"});} void add(SQLiteDatabase d,String n,String ins,String[] xs){ContentValues v=new ContentValues();v.put("recipe_name",n);v.put("instructions",ins);long id=d.insert("recipe",null,v);for(String x:xs){ContentValues i=new ContentValues();i.put("recipe_id",id);i.put("ingredient_name",x);i.put("required_quantity",1);d.insert("recipe_ingredient",null,i);}} public long insert(PantryItem p){ContentValues v=new ContentValues();v.put("ingredient_name",p.name);v.put("quantity",p.quantity);v.put("unit",p.unit);return getWritableDatabase().insert("pantry_item",null,v);} public List<PantryItem> all(){List<PantryItem> r=new ArrayList<>();Cursor c=getReadableDatabase().query("pantry_item",null,null,null,null,null,"ingredient_name");while(c.moveToNext())r.add(new PantryItem(c.getLong(0),c.getString(1),c.getDouble(2),c.getString(3),c.getString(4),c.getString(5)));c.close();return r;} public int delete(long id){return getWritableDatabase().delete("pantry_item","id=?",new String[]{String.valueOf(id)});} public void onUpgrade(SQLiteDatabase d,int o,int n){} }